#include <fcntl.h>

int main() {
    // Create a shared memory region
    int shm_fd = open("/dev/shm/shared_memory", O_RDWR | O_CREAT, 0644);
    struct shmid_ds shm_buf;
    shm_getsid(shm_fd, &shm_buf);
